mapper.select:
SELECT T.RNUM, T.BILL_NO, T.BILL_TITLE, T.FILE_GROUP_NO, T.BILL_STATUS, T.BILL_DATE , T.STORE_ORDER_NO, T.STORE_NO, T.STORE_ORDER_DATE, T.STORE_ORDER_STATUS, T.STORE_ORDER_SUM , T.STORE_ORDER_TITLE , T.STORE_LAT, T.STORE_LOT, T.STORE_ADDR1, T.STORE_ZIP, T.STORE_NM , T.STORE_ADDR2, T.STORE_OPEN_DATE, T.STORE_STATUS , T.FILE_GROUP_NM, T.FILE_REGDATE, T.FILE_GROUP_TY, T.FILE_NO, T.FILE_ORIGINAL_NAME , T.FILE_SAVE_NAME, T.FILE_EXT, T.FILE_SIZE, T.FILE_SAVE_LOCATE, T.FILE_MIME , T.FILE_FANCYSIZE, T.FILE_SAVE_DATE, T.FILE_DOWNCOUNT FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.BILL_NO DESC) AS RNUM , B.BILL_NO, B.BILL_TITLE, B.FILE_GROUP_NO, B.BILL_STATUS, B.BILL_DATE , SO.STORE_ORDER_NO, SO.STORE_NO, SO.STORE_ORDER_DATE, SO.STORE_ORDER_STATUS, SO.STORE_ORDER_SUM , SO.STORE_ORDER_TITLE , S.STORE_LAT, S.STORE_LOT, S.STORE_ADDR1, S.STORE_ZIP, S.STORE_NM , S.STORE_ADDR2, S.STORE_OPEN_DATE, S.STORE_STATUS , FG.FILE_GROUP_NM, FG.FILE_REGDATE, FG.FILE_GROUP_TY , FD.FILE_NO, FD.FILE_ORIGINAL_NAME, FD.FILE_SAVE_NAME, FD.FILE_EXT , FD.FILE_SIZE, FD.FILE_SAVE_LOCATE, FD.FILE_MIME, FD.FILE_FANCYSIZE , FD.FILE_SAVE_DATE, FD.FILE_DOWNCOUNT FROM BILL B LEFT JOIN STORE_ORDER SO ON B.BILL_NO = SO.BILL_NO LEFT JOIN STORE S ON SO.STORE_NO = S.STORE_NO LEFT JOIN FILE_GROUP FG ON B.FILE_GROUP_NO = FG.FILE_GROUP_NO LEFT JOIN FILE_DETAIL FD ON FG.FILE_GROUP_NO = FD.FILE_GROUP_NO WHERE 1 = 1
AND ( TO_CHAR(B.BILL_NO) LIKE '%' || #{keyword} || '%' OR B.BILL_TITLE LIKE '%' || #{keyword} || '%' OR TO_CHAR(B.BILL_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR (B.BILL_STATUS = '1' AND '계산완료' LIKE '%' || #{keyword} || '%') OR (B.BILL_STATUS = '2' AND '반려' LIKE '%' || #{keyword} || '%') )
) T WHERE T.RNUM BETWEEN (#{currentPage} * 10) - (10-1) AND (#{currentPage} *10)

mapper.update:
UPDATE STORE_ORDER
SET STORE_ORDER_STATUS = 4
WHERE STORE_ORDER_NO IN

	#{item.storeOrderNo}

AND STORE_NO IN

    #{item.storeNo}

UPDATE BILL
SET BILL_TITLE = #{billTitle}
    , BILL_DATE = #{billDate} 
    , BILL_STATUS = 1

    ,FILE_GROUP_NO =  #{fileGroupNo}

WHERE BILL_NO = #{billNo}

mapper.select:
SELECT T.RNUM, T.BILL_NO, T.BILL_TITLE, T.FILE_GROUP_NO, T.BILL_STATUS, T.BILL_DATE , T.STORE_ORDER_NO, T.STORE_NO, T.STORE_ORDER_DATE, T.STORE_ORDER_STATUS, T.STORE_ORDER_SUM , T.STORE_ORDER_TITLE , T.STORE_LAT, T.STORE_LOT, T.STORE_ADDR1, T.STORE_ZIP, T.STORE_NM , T.STORE_ADDR2, T.STORE_OPEN_DATE, T.STORE_STATUS , T.FILE_GROUP_NM, T.FILE_REGDATE, T.FILE_GROUP_TY, T.FILE_NO, T.FILE_ORIGINAL_NAME , T.FILE_SAVE_NAME, T.FILE_EXT, T.FILE_SIZE, T.FILE_SAVE_LOCATE, T.FILE_MIME , T.FILE_FANCYSIZE, T.FILE_SAVE_DATE, T.FILE_DOWNCOUNT FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.BILL_NO DESC) AS RNUM , B.BILL_NO, B.BILL_TITLE, B.FILE_GROUP_NO, B.BILL_STATUS, B.BILL_DATE , SO.STORE_ORDER_NO, SO.STORE_NO, SO.STORE_ORDER_DATE, SO.STORE_ORDER_STATUS, SO.STORE_ORDER_SUM , SO.STORE_ORDER_TITLE , S.STORE_LAT, S.STORE_LOT, S.STORE_ADDR1, S.STORE_ZIP, S.STORE_NM , S.STORE_ADDR2, S.STORE_OPEN_DATE, S.STORE_STATUS , FG.FILE_GROUP_NM, FG.FILE_REGDATE, FG.FILE_GROUP_TY , FD.FILE_NO, FD.FILE_ORIGINAL_NAME, FD.FILE_SAVE_NAME, FD.FILE_EXT , FD.FILE_SIZE, FD.FILE_SAVE_LOCATE, FD.FILE_MIME, FD.FILE_FANCYSIZE , FD.FILE_SAVE_DATE, FD.FILE_DOWNCOUNT FROM BILL B LEFT JOIN STORE_ORDER SO ON B.BILL_NO = SO.BILL_NO LEFT JOIN STORE S ON SO.STORE_NO = S.STORE_NO LEFT JOIN FILE_GROUP FG ON B.FILE_GROUP_NO = FG.FILE_GROUP_NO LEFT JOIN FILE_DETAIL FD ON FG.FILE_GROUP_NO = FD.FILE_GROUP_NO WHERE 1 = 1 AND SO.STORE_NO = #{storeNo}
AND ( TO_CHAR(B.BILL_NO) LIKE '%' || #{keyword} || '%' OR B.BILL_TITLE LIKE '%' || #{keyword} || '%' OR TO_CHAR(B.BILL_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR (B.BILL_STATUS = '1' AND '계산완료' LIKE '%' || #{keyword} || '%') OR (B.BILL_STATUS = '2' AND '반려' LIKE '%' || #{keyword} || '%') )
) T WHERE T.RNUM BETWEEN (#{currentPage} * 10) - (10-1) AND (#{currentPage} *10)

SELECT COUNT(*) FROM ( SELECT B.BILL_NO AS NO, B.BILL_TITLE AS TITLE, B.BILL_STATUS AS BILL_STATUS, B.BILL_DATE AS STATUS_DATE, SO.STORE_NO AS STORE_NO FROM BILL B JOIN STORE_ORDER SO ON B.BILL_NO = SO.BILL_NO WHERE 1 = 1 AND SO.STORE_NO = #{storeNo}
AND ( TO_CHAR(B.BILL_NO) LIKE '%' || #{keyword} || '%' OR B.BILL_TITLE LIKE '%' || #{keyword} || '%' OR TO_CHAR(B.BILL_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR (B.BILL_STATUS = '1' AND '계산완료' LIKE '%' || #{keyword} || '%') OR (B.BILL_STATUS = '2' AND '반려' LIKE '%' || #{keyword} || '%') )
UNION ALL
SELECT STORE_ORDER_NO AS NO, STORE_ORDER_TITLE AS TITLE, STORE_ORDER_STATUS AS ORDER_STATUS, STORE_ORDER_DATE AS STATUS_DATE, STORE_NO AS STORE_NO FROM STORE_ORDER WHERE 1 = 1 AND STORE_NO = #{storeNo}
AND ( STORE_ORDER_TITLE LIKE '%' || #{keyword} || '%' OR TO_CHAR(STORE_ORDER_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR (STORE_ORDER_STATUS = '1' AND '계산완료' LIKE '%' || #{keyword} || '%') OR (STORE_ORDER_STATUS = '2' AND '미승인' LIKE '%' || #{keyword} || '%') OR (STORE_ORDER_STATUS = '3' AND '회수' LIKE '%' || #{keyword} || '%') OR (STORE_ORDER_STATUS = '4' AND '반려' LIKE '%' || #{keyword} || '%') )
) T WHERE 1 = 1
